const KEY='asset-next-v1';
const defs=[['cash','현금 · 예적금','바로 사용할 수 있는 자금','원'],['pension','퇴직연금','인출 가능 여부를 확인하세요','원'],['stocks','주식','현재 평가액 입력','원'],['gold','금','순금 보유량 · 1돈 = 3.75g','돈'],['usd','미국 달러','USD 보유액','달러'],['jpy','일본 엔','JPY 보유액','엔'],['eur','유로','EUR 보유액','유로']];
const initial=()=>({amounts:Object.fromEntries(defs.map(([k])=>[k,0])),use:Object.fromEntries(defs.map(([k])=>[k,k!=='pension'])),usdRate:0,jpyRate:0,eurRate:0,goldRate:0,fxDate:'',goldDate:'',rateSource:'',otherDebt:0,repayDebt:0,reserve:0,marketQuotes:{},autoMarket:true,properties:[],type:'home',plans:{home:{ltv:80,cost:0,cap:''},commercial:{ltv:70,cost:0,cap:''}}});
const $=s=>document.querySelector(s),n=v=>Math.max(0,Number.isFinite(Number(v))?Number(v):0),won=v=>Math.floor(v).toLocaleString('ko-KR')+'원';
function concise(v){if(v>=1e8)return (v/1e8).toLocaleString('ko-KR',{maximumFractionDigits:2})+'억 원';if(v>=1e4)return (v/1e4).toLocaleString('ko-KR',{maximumFractionDigits:0})+'만 원';return won(v)}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let state=initial();try{const s=localStorage.getItem(KEY);if(s)state=validate(JSON.parse(s))}catch{}
function validate(s){if(!s||typeof s!=='object'||!s.amounts||!s.plans||!Array.isArray(s.properties)||s.properties.length>100)throw Error('잘못된 백업 형식');const a=initial();for(const [k]of defs){a.amounts[k]=n(s.amounts[k]);a.use[k]=s.use?.[k]===true}for(const k of ['usdRate','jpyRate','eurRate','goldRate','otherDebt','repayDebt','reserve'])a[k]=n(s[k]);for(const k of ['fxDate','goldDate','rateSource'])a[k]=String(s[k]||'').slice(0,200);a.autoMarket=s.autoMarket===true;a.marketQuotes={};for(const k of ['usd','jpy','eur','gold']){const q=s.marketQuotes?.[k];if(q&&n(q.value)>0&&typeof q.asOf==='string')a.marketQuotes[k]={value:n(q.value),asOf:q.asOf.slice(0,40),source:String(q.source||'네이버 증권').slice(0,100)}};a.type=s.type==='commercial'?'commercial':'home';for(const k of ['home','commercial'])a.plans[k]={ltv:Math.min(95,n(s.plans[k]?.ltv)),cost:Math.min(100,n(s.plans[k]?.cost)),cap:s.plans[k]?.cap===''?'':n(s.plans[k]?.cap)};a.properties=s.properties.map(p=>({address:String(p.address||'').slice(0,300),kind:['house','apartment','land','building'].includes(p.kind)?p.kind:'house',unit:String(p.unit||'').slice(0,100),date:String(p.date||'').slice(0,30),value:n(p.value),area:n(p.area),share:Math.min(100,n(p.share)),debt:n(p.debt),saleCost:n(p.saleCost),sell:p.sell===true}));return a}
function calculate(s){const vals={...s.amounts,gold:s.amounts.gold*s.goldRate,usd:s.amounts.usd*s.usdRate,jpy:s.amounts.jpy*s.jpyRate/100,eur:s.amounts.eur*s.eurRate};const financial=Object.values(vals).reduce((a,b)=>a+b,0);let prop=0,propDebt=0,sales=0;for(const p of s.properties){const value=p.value*(p.kind==='land'?p.area:1)*p.share/100;prop+=value;propDebt+=p.debt;if(p.sell)sales+=value-p.debt-p.saleCost}const usable=Object.keys(vals).reduce((a,k)=>a+(s.use[k]?vals[k]:0),0);const raw=usable+sales-Math.min(s.repayDebt,s.otherDebt)-s.reserve;const A=Math.max(0,raw),p=s.plans[s.type],L=p.ltv/100,C=p.cost/100,cap=p.cap===''?Infinity:n(p.cap);const price=Math.max(0,Math.min(A/(1-L+C),(A+cap)/(1+C))),loan=Math.min(price*L,cap),fees=price*C;return{vals,financial,prop,debts:propDebt+s.otherDebt,gross:financial+prop,net:financial+prop-propDebt-s.otherDebt,A,raw,price,loan,fees,equity:price+fees-loan}}
let lastSerialized=localStorageSafe(KEY)||'', previous=localStorageSafe(KEY+'-previous'), records=[];
function localStorageSafe(k){try{return localStorage.getItem(k)}catch{return null}}
try{records=JSON.parse(localStorageSafe(KEY+'-records')||'[]').map(r=>({...r,state:validate(r.state)}))}catch{document.getElementById('storageMessage').textContent='저장 기록을 읽지 못했습니다. 현재 입력은 유지됩니다.'}
function persist(){const serialized=JSON.stringify(state);try{if(serialized!==lastSerialized){if(lastSerialized){localStorage.setItem(KEY+'-previous',lastSerialized);previous=lastSerialized}localStorage.setItem(KEY,serialized);lastSerialized=serialized;localStorage.setItem(KEY+'-savedAt',new Date().toISOString())}const at=localStorage.getItem(KEY+'-savedAt');$('#saveState').textContent='● 이 브라우저에 저장됨';$('#savedAt').textContent=at?'자동 저장 '+new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'현재 입력 저장됨'}catch{$('#saveState').textContent='저장 실패';$('#storageMessage').textContent='브라우저 저장 공간이 부족하거나 차단됐습니다. 전체 기록 백업을 내려받으세요.'}}
function renderAssets(){ $('#assetRows').innerHTML=defs.map(([k,title,desc,unit])=>`<div class="asset-row"><input type="checkbox" data-use="${k}" aria-label="${title} 매수 자금에 포함" ${state.use[k]?'checked':''}><label for="amount-${k}">${title}<small>${desc}</small></label><input id="amount-${k}" type="number" min="0" step="any" data-amount="${k}" value="${state.amounts[k]||''}" placeholder="0"><span class="unit">${unit}</span><span class="asset-value" id="value-${k}"></span></div>`).join('')}
function renderProperties(){ $('#propertyRows').innerHTML=state.properties.length?state.properties.map((p,i)=>`<div class="property-card"><div class="property-head"><b>보유 부동산 ${String(i+1).padStart(2,'0')}</b><button data-remove="${i}">삭제</button></div><div class="fields"><label>부동산 유형<select data-prop="${i}:kind"><option value="house" ${p.kind==='house'?'selected':''}>개별주택</option><option value="apartment" ${p.kind==='apartment'?'selected':''}>공동주택</option><option value="land" ${p.kind==='land'?'selected':''}>토지</option><option value="building" ${p.kind==='building'?'selected':''}>비주택 건물</option></select></label><label>평가 기준일<input type="date" data-prop="${i}:date" value="${esc(p.date)}"></label></div><label>주소 · 시 / 군 / 구 · 읍 / 면 · 리 / 동 · 번지<input data-prop="${i}:address" value="${esc(p.address)}" placeholder="예: ○○시 ○○면 ○○리 123-4"></label><div class="fields"><label>동 · 호수 / 건물명<input data-prop="${i}:unit" value="${esc(p.unit)}" placeholder="공동주택은 동·호수 필수 확인"></label><label>보유 지분 · %<input type="number" min="0" max="100" data-prop="${i}:share" value="${p.share}"></label><label>${p.kind==='land'?'㎡당 공시지가 · 원':p.kind==='building'?'직접 평가한 전체 가액 · 원':'전체 주택 공시가격 · 원'}<input type="number" min="0" data-prop="${i}:value" value="${p.value||''}" placeholder="0"></label>${p.kind==='land'?`<label>토지 면적 · ㎡<input type="number" min="0" step="any" data-prop="${i}:area" value="${p.area||''}"></label>`:''}<label>내 지분의 대출 · 반환보증금 합계 · 원<input type="number" min="0" data-prop="${i}:debt" value="${p.debt||''}" placeholder="0"></label><label>내 부담 매각비용 · 원<input type="number" min="0" data-prop="${i}:saleCost" value="${p.saleCost||''}" placeholder="0"></label></div><label class="checkbox-label"><input type="checkbox" data-prop="${i}:sell" ${p.sell?'checked':''}>매각 후 잔액을 매수 자금에 포함</label><p class="sub" id="prop-result-${i}"></p></div>`).join(''):'<div class="empty">아직 등록된 부동산이 없습니다.<br>주소와 평가액을 추가해 총자산을 확인하세요.</div>'}
function sync(){for(const e of document.querySelectorAll('[data-key]'))e.value=state[e.dataset.key]||'';for(const e of document.querySelectorAll('[data-plan]'))e.value=state.plans[state.type][e.dataset.plan];document.querySelectorAll('[data-type]').forEach(e=>e.classList.toggle('selected',e.dataset.type===state.type))}
function update(){const r=calculate(state);for(const k of ['net','gross','debts','financial','available','maxPrice','equity','loan','fees']){const v=({available:r.A,maxPrice:r.price})[k]??r[k];$('#'+k).textContent=concise(v)}$('#priceExact').textContent=won(r.price);$('#ltvLabel').textContent=state.plans[state.type].ltv+'%';for(const[k]of defs){$('#value-'+k).textContent=won(r.vals[k])}state.properties.forEach((p,i)=>{const v=p.value*(p.kind==='land'?p.area:1)*p.share/100;$('#prop-result-'+i).textContent='내 지분 평가액 '+won(v)+' · 부채 제외 '+won(v-p.debt)+' · '+(p.kind==='building'?'직접 평가액':'공시가격 기준')});const warns=[];if(['usd','jpy','eur'].some(k=>state.amounts[k]>0&&(!state[k+'Rate']||!state.fxDate)))warns.push('외화 보유액이 있습니다. 환율과 실제 고시일을 확인하세요.');if(state.amounts.gold>0&&(!state.goldRate||!state.goldDate))warns.push('금 평가단가와 가격 기준일을 확인하세요.');if(state.use.pension&&state.amounts.pension>0)warns.push('퇴직연금을 매수 자금에 포함했습니다. 인출 조건과 세후 수령액을 확인하세요.');if(state.repayDebt>state.otherDebt)warns.push('기타 부채 상환액은 입력한 부채 잔액까지만 차감했습니다.');if(r.raw<0)warns.push('상환액·예비자금이 사용 가능 자산을 초과하여 매수 가능 금액을 0원으로 계산했습니다.');if(state.properties.some(p=>p.sell))warns.push('선택한 부동산이 입력 평가액에 매각된다는 가정입니다. 실제 매각대금·양도세를 확인하세요.');if(!state.plans[state.type].cost)warns.push('취득 부대비용률이 0%입니다. 실제 비용을 입력하면 매수 가능 가격이 줄어듭니다.');$('#warnings').textContent=warns.join(' ')||'입력한 평가 기준일과 금액을 확인한 뒤 결과를 사용하세요.';$('#compare').innerHTML=[80,70].map(l=>`<div class="scenario"><span>대출 ${l}% · 자기자금 ${100-l}%</span><b>${concise(r.A/(1-l/100))}</b></div><p class="sub">대출 ${won(r.A/(1-l/100)-r.A)}</p>`).join('');persist()}
document.addEventListener('input',e=>{const d=e.target.dataset;if(d.amount)state.amounts[d.amount]=n(e.target.value);else if(d.use)state.use[d.use]=e.target.checked;else if(d.key)state[d.key]=['fxDate','goldDate','rateSource'].includes(d.key)?e.target.value:n(e.target.value);else if(d.plan){const v=e.target.value;state.plans[state.type][d.plan]=d.plan==='cap'&&v===''?'':Math.min(d.plan==='ltv'?95:d.plan==='cost'?100:1e16,n(v))}else if(d.prop){const[i,k]=d.prop.split(':');state.properties[i][k]=k==='sell'?e.target.checked:['address','unit','date','kind'].includes(k)?e.target.value:Math.min(k==='share'?100:1e16,n(e.target.value));if(k==='kind')renderProperties()}else return;update()});
document.addEventListener('click',e=>{if(e.target.dataset.type){state.type=e.target.dataset.type;sync();update()}if(e.target.dataset.remove!==undefined){state.properties.splice(Number(e.target.dataset.remove),1);renderProperties();update()}});
$('#addProperty').onclick=()=>{state.properties.push({address:'',kind:'house',unit:'',date:'',value:0,area:0,share:100,debt:0,saleCost:0,sell:false});renderProperties();update()};
function renderAll(){renderAssets();renderProperties();sync();update();renderRecords();renderMarket();$('#autoMarket').checked=state.autoMarket}
$('#example').onclick=()=>{if(!confirm('현재 입력을 예시 데이터로 바꿀까요? 필요한 경우 먼저 백업해주세요.'))return;state=initial();Object.assign(state.amounts,{cash:100000000,pension:50000000,stocks:30000000,gold:10,usd:10000,jpy:500000,eur:2000});Object.assign(state,{usdRate:1400,jpyRate:950,eurRate:1500,goldRate:500000,rateSource:'계산 설명용 가상 단가 · 실제 시세 아님',reserve:20000000});state.properties=[{address:'예시 주소 · 실제 부동산 아님',kind:'land',unit:'',date:'',value:200000,area:300,share:100,debt:10000000,saleCost:0,sell:false}];renderAll();alert('예시 데이터입니다. 환율·금 가격·부동산 가액은 실제 현재 가격이 아닙니다.')};
$('#reset').onclick=()=>{if(confirm('이 브라우저에 저장한 모든 입력을 삭제할까요?')){state=initial();renderAll()}};

function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export').onclick=()=>download(state,'나의-자산-백업.json');
$('#exportAll').onclick=()=>download({version:2,exportedAt:new Date().toISOString(),current:state,records},'나의-자산-전체-백업.json');
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('5MB 이하 파일만 지원합니다');const data=JSON.parse(await f.text()),next=validate(data.version===2?data.current:data);let nextRecords=records;if(data.version===2){if(!Array.isArray(data.records)||data.records.length>100)throw Error('기록 형식 오류');nextRecords=data.records.map(r=>({id:String(r.id),name:String(r.name).slice(0,60),at:String(r.at),state:validate(r.state)}))}if(confirm('현재 입력'+(data.version===2?'과 저장 기록을':'을')+' 백업 내용으로 바꿀까요?')){if(data.version===2)localStorage.setItem(KEY+'-records',JSON.stringify(nextRecords));records=nextRecords;state=next;renderAll()}}catch(err){alert('백업을 열 수 없습니다. '+err.message)}e.target.value=''};
function renderRecords(){$('#records').innerHTML=records.length?records.map(r=>`<div class="saved-record"><div><b>${esc(r.name)}</b><small>${esc(new Date(r.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))} · 순자산 ${concise(calculate(r.state).net)}</small></div><div><button data-load-record="${esc(r.id)}">불러오기</button><button data-delete-record="${esc(r.id)}">삭제</button></div></div>`).join(''):'<p class="sub">별도 저장한 기록이 없습니다. 이름을 입력하고 기록 저장을 눌러주세요.</p>'}
$('#saveRecord').onclick=()=>{const name=$('#recordName').value.trim();if(!name){$('#recordName').focus();return alert('기록 이름을 입력해주세요.')}if(records.length>=100)return alert('최대 100개까지 보관할 수 있습니다. 전체 백업 후 불필요한 기록을 삭제해주세요.');const r={id:crypto.randomUUID(),name,at:new Date().toISOString(),state:JSON.parse(JSON.stringify(state))};const next=[r,...records];try{localStorage.setItem(KEY+'-records',JSON.stringify(next));records=next;renderRecords();$('#storageMessage').textContent='“'+name+'” 기록을 저장했습니다.';$('#recordName').value=''}catch{$('#storageMessage').textContent='기록 저장에 실패했습니다. 전체 백업을 내려받으세요.'}};
$('#recover').onclick=()=>{if(!previous)return alert('복구할 이전 입력이 없습니다.');if(confirm('마지막 변경 전 입력으로 복구할까요?')){try{state=validate(JSON.parse(previous));renderAll()}catch{alert('이전 입력을 복구하지 못했습니다.')}}};
document.addEventListener('click',e=>{const load=e.target.dataset.loadRecord,del=e.target.dataset.deleteRecord;if(load){const r=records.find(r=>r.id===load);if(r&&confirm('현재 입력을 “'+r.name+'” 기록으로 바꿀까요?')){state=validate(r.state);renderAll()}}if(del&&confirm('이 저장 기록을 삭제할까요?')){const next=records.filter(r=>r.id!==del);try{localStorage.setItem(KEY+'-records',JSON.stringify(next));records=next;renderRecords()}catch{alert('삭제에 실패했습니다.')}}});
function todaySeoul(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date())}
function renderMarket(){$('#marketQuotes').innerHTML=Object.entries(state.marketQuotes||{}).map(([key,q])=>{const date=String(q.asOf||'').slice(0,10);return `<div class="quote"><span>${esc(({usd:'USD · 1달러',jpy:'JPY · 100엔',eur:'EUR · 1유로',gold:'순금 평가 · 1돈'})[key]||key)} <b>${Number(q.value).toLocaleString('ko-KR',{maximumFractionDigits:2})}원</b></span><small>${esc(q.source)} · ${esc(String(q.asOf||'').replace('T',' '))} ${date===todaySeoul()?'· 당일 고시':'· 이전 고시'}</small></div>`}).join('')}
$('#autoMarket').onchange=e=>{state.autoMarket=e.target.checked;update()};
async function fetchMarket(){const b=$('#fetchMarket');b.disabled=true;$('#marketStatus').textContent='네이버 최신 시세를 조회하고 있습니다…';try{const r=await fetch('/api/market',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('시세 서버 응답 오류');const data=await r.json();if(!data.quotes||!Object.keys(data.quotes).length)throw Error('조회된 시세 없음');for(const [key,q]of Object.entries(data.quotes)){if(!['usd','jpy','eur','gold'].includes(key)||!Number.isFinite(q.value)||q.value<=0)continue;state[key+'Rate']=q.value;state.marketQuotes[key]=q}const fx=Object.entries(state.marketQuotes).filter(([k])=>k!=='gold').map(([,q])=>q.asOf.slice(0,10));state.fxDate=fx.sort()[0]||state.fxDate;state.goldDate=state.marketQuotes.gold?.asOf.slice(0,10)||state.goldDate;state.rateSource='네이버 증권 · 환율: 하나은행 매매기준율 / 금: 신한은행 국내 금 기준가';sync();renderMarket();update();
$('#marketStatus').textContent='조회 완료 (한국시간) · '+new Date(data.fetchedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+'. '+(data.errors?.length?'일부 조회 실패: '+data.errors.join(', ')+'. 기존 단가 유지. ':'')+(Object.values(data.quotes).some(q=>q.asOf.slice(0,10)!==todaySeoul())?'당일 고시가 없는 항목은 이전 고시일을 표시합니다.':'당일 고시 자료입니다.');
}catch(err){$('#marketStatus').textContent='조회 실패 · 기존 단가를 유지합니다. 잠시 후 재시도하거나 직접 입력해주세요.'}finally{b.disabled=false}}
$('#fetchMarket').onclick=fetchMarket;
// A manual edit is no longer labelled as an automatically fetched quote.
document.addEventListener('input',e=>{const k=e.target.dataset.key;if(['usdRate','jpyRate','eurRate','goldRate'].includes(k)){delete state.marketQuotes[k.replace('Rate','')];renderMarket();persist()}});
renderAll();if(state.autoMarket)fetchMarket();
